// Generated release data. Canonical SQL belongs to the closed version sources.
export const MATERIAL_CLOSURE_RELEASE = Object.freeze({"version":"identity-admission-closure-v1","checksum":"f86719e28916af64016ca46001e361a73a55c20fe95721dc5a6e5e640c1cb22a","manifestSha256":"d9cdee9b2a67a496526b4e91cab73239a37b8e22ead5e18d25738f4978a1ee2f","sql":"-- Core schema version identity-admission-closure-v1 (closed build artifact).\n\nSET ROLE backbone_gov;\n\n-- gov/identity_budget_totals.sql\n\n-- Private, payload-free accounting sees the whole mandate subtree. General run\n-- and effect SELECT policies remain restricted to the caller's project/secret.\nCREATE FUNCTION gov.identity_budget_totals(p_mandate uuid) RETURNS TABLE(tokens numeric,cost numeric,effects bigint)\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog\nAS $$\nDECLARE old_person text:=coalesce(current_setting('backbone.principal',true),''); old_run text:=coalesce(current_setting('backbone.run',true),''); old_secret text:=coalesce(current_setting('backbone.secret',true),'');\nBEGIN\n  PERFORM set_config('backbone.run','',true); PERFORM set_config('backbone.secret','',true); PERFORM set_config('backbone.principal',sec.system_principal()::text,true);\n  SELECT coalesce(sum(r.tokens_used),0),coalesce(sum(r.cost_micros),0) INTO tokens,cost\n  FROM app.runs r WHERE r.workspace_id=sec.current_workspace() AND r.mandate_id IN(SELECT gov._subtree(p_mandate));\n  SELECT count(*) INTO effects FROM app.effects e WHERE e.workspace_id=sec.current_workspace()\n    AND e.mandate_id IN(SELECT gov._subtree(p_mandate)) AND e.status NOT IN('denied','cancelled');\n  PERFORM set_config('backbone.principal',old_person,true); PERFORM set_config('backbone.run',old_run,true); PERFORM set_config('backbone.secret',old_secret,true);\n  RETURN NEXT;\nEXCEPTION WHEN OTHERS THEN\n  PERFORM set_config('backbone.principal',old_person,true); PERFORM set_config('backbone.run',old_run,true); PERFORM set_config('backbone.secret',old_secret,true);\n  RAISE;\nEND\n$$;\nREVOKE ALL ON FUNCTION gov.identity_budget_totals(uuid) FROM PUBLIC,backbone_app,backbone_operator;\n\n-- gov/_mandate_standing.sql\n\n-- Whether a mandate still stands: 'ok', or why not. A budget is charged to every ancestor, so a\n-- child cannot reset its root's limit: each ancestor's limit counts everything spent beneath it.\nCREATE OR REPLACE FUNCTION gov._mandate_standing(p_mandate uuid) RETURNS text\nLANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE\n  m record;\n  a record;\n  tokens numeric;\n  cost numeric;\n  effects bigint;\nBEGIN\n  SELECT * INTO m FROM app.mandates WHERE workspace_id = sec.current_workspace() AND id = p_mandate;\n  IF NOT FOUND OR m.revoked_at IS NOT NULL THEN\n    RETURN 'mandate_revoked';\n  END IF;\n  IF m.expires_at <= clock_timestamp() THEN\n    RETURN 'mandate_expired';\n  END IF;\n  FOR a IN SELECT x.* FROM app.mandates x WHERE x.workspace_id = m.workspace_id AND x.id IN (SELECT gov._ancestors(p_mandate)) LOOP\n    IF a.revoked_at IS NOT NULL THEN\n      RETURN 'mandate_revoked';\n    END IF;\n    IF a.max_tokens IS NULL AND a.max_cost_micros IS NULL AND a.max_effects IS NULL THEN\n      CONTINUE;\n    END IF;\n    SELECT b.tokens,b.cost,b.effects INTO tokens,cost,effects FROM gov.identity_budget_totals(a.id) b;\n    IF (a.max_tokens IS NOT NULL AND tokens >= a.max_tokens) OR (a.max_cost_micros IS NOT NULL AND cost >= a.max_cost_micros)\n       OR (a.max_effects IS NOT NULL AND effects >= a.max_effects) THEN\n      RETURN 'budget_exhausted';\n    END IF;\n  END LOOP;\n  RETURN 'ok';\nEND\n$$;\n\n-- gov/identity_bind_task.sql\n\n-- Bind an existing task only by its requester, with write access to both projects.\nCREATE OR REPLACE FUNCTION gov.identity_bind_task(p_project uuid,p_task uuid) RETURNS uuid\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE me uuid; prior_project uuid;\nBEGIN\n  PERFORM gov._lock_workspace(); me:=gov._person();\n  IF coalesce(gov.identity_project_access(p_project),'') NOT IN('owner','editor') OR NOT EXISTS(SELECT FROM app.tasks WHERE workspace_id=sec.current_workspace() AND id=p_task AND requested_by=me) THEN RAISE EXCEPTION 'denied: task binding belongs to its requester'; END IF;\n  SELECT project_id INTO prior_project FROM app.identity_task_projects WHERE workspace_id=sec.current_workspace() AND task_id=p_task;\n  IF EXISTS(SELECT FROM app.identity_task_projects x WHERE x.workspace_id=sec.current_workspace() AND x.task_id=p_task\n    AND coalesce(gov.identity_project_access(x.project_id),'') NOT IN('owner','editor')) THEN RAISE EXCEPTION 'denied: current project is not writable'; END IF;\n  INSERT INTO app.identity_task_projects(workspace_id,task_id,project_id) VALUES(sec.current_workspace(),p_task,p_project)\n    ON CONFLICT(workspace_id,task_id) DO UPDATE SET project_id=EXCLUDED.project_id;\n  -- Audience history is append-only. Destination readers participate in every\n  -- publication decision even if the task was private before this binding.\n  INSERT INTO app.task_people(workspace_id,task_id,person_id)\n  SELECT sec.current_workspace(),p_task,p.owner_id FROM app.identity_projects p WHERE p.workspace_id=sec.current_workspace() AND p.project_id=p_project AND p.owner_id<>me\n  UNION SELECT sec.current_workspace(),p_task,a.person_id FROM app.identity_project_people a WHERE a.workspace_id=sec.current_workspace() AND a.project_id=p_project AND a.person_id<>me\n  ON CONFLICT(workspace_id,task_id,person_id) DO NOTHING;\n  DELETE FROM app.identity_project_people WHERE workspace_id=sec.current_workspace() AND project_id=p_task AND prior_project=p_task AND p_task<>p_project AND NOT EXISTS(SELECT FROM app.identity_task_projects WHERE workspace_id=sec.current_workspace() AND project_id=p_task);\n  DELETE FROM app.identity_workspace_projects WHERE workspace_id=sec.current_workspace() AND project_id=p_task AND prior_project=p_task AND p_task<>p_project AND NOT EXISTS(SELECT FROM app.identity_task_projects WHERE workspace_id=sec.current_workspace() AND project_id=p_task);\n  DELETE FROM app.identity_projects WHERE workspace_id=sec.current_workspace() AND project_id=p_task AND prior_project=p_task AND p_task<>p_project AND NOT EXISTS(SELECT FROM app.identity_task_projects WHERE workspace_id=sec.current_workspace() AND project_id=p_task);\n  RETURN p_task;\nEND\n$$;\nREVOKE ALL ON FUNCTION gov.identity_bind_task(uuid,uuid) FROM PUBLIC,backbone_operator;\nGRANT EXECUTE ON FUNCTION gov.identity_bind_task(uuid,uuid) TO backbone_app;\n\n-- gov/_task_read_beyond.sql\n\n-- Whether a task is read by anyone but one person: shared with the workspace, joined by others, or\n-- bound to a group channel thread.\nCREATE OR REPLACE FUNCTION gov._task_read_beyond(p_task uuid, p_person uuid) RETURNS boolean\nLANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog\nAS $$\n  SELECT EXISTS (\n    SELECT FROM app.tasks t WHERE t.workspace_id = sec.current_workspace() AND t.id = p_task\n      AND (t.visibility = 'workspace' OR p_person NOT IN (t.requested_by, t.on_behalf_of)\n           OR EXISTS (SELECT FROM app.task_people tp WHERE tp.workspace_id = t.workspace_id AND tp.task_id = t.id AND tp.person_id <> p_person)\n           OR EXISTS (SELECT FROM app.identity_task_projects b JOIN app.identity_projects p ON p.workspace_id=b.workspace_id AND p.project_id=b.project_id\n             WHERE b.workspace_id=t.workspace_id AND b.task_id=t.id AND (p.owner_id<>p_person\n               OR EXISTS(SELECT FROM app.identity_project_people a WHERE a.workspace_id=b.workspace_id AND a.project_id=b.project_id AND a.person_id<>p_person)\n               OR EXISTS(SELECT FROM app.identity_workspace_projects w WHERE w.workspace_id=b.workspace_id AND w.project_id=b.project_id)))\n           OR EXISTS (SELECT FROM app.channel_threads ct WHERE ct.workspace_id = t.workspace_id AND ct.task_id = t.id AND ct.kind = 'group')))\n$$;\n\n-- gov/_quote_run.sql\n\n-- A run that quotes other work takes what that work carries. Its own person's work passes on its\n-- reasons in its words; another person's only that it read such material, never why.\nCREATE OR REPLACE FUNCTION gov._quote_run(p_run uuid, p_quoted uuid) RETURNS void\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE\n  old_person text:=coalesce(current_setting('backbone.principal',true),''); old_run text:=coalesce(current_setting('backbone.run',true),''); old_secret text:=coalesce(current_setting('backbone.secret',true),'');\n  ws uuid := sec.current_workspace();\n  me record;\n  q record;\n  mine boolean;\n  private_reason text;\nBEGIN\n  PERFORM set_config('backbone.run','',true); PERFORM set_config('backbone.secret','',true); PERFORM set_config('backbone.principal',sec.system_principal()::text,true);\n  SELECT r.task_id, gov._run_person(r.id) AS person INTO me FROM app.runs r WHERE r.workspace_id = ws AND r.id = p_run;\n  SELECT r.*, gov._run_person(r.id) AS person INTO q FROM app.runs r WHERE r.workspace_id = ws AND r.id = p_quoted;\n  IF NOT FOUND OR p_quoted = p_run OR NOT (q.tainted_untrusted OR q.tainted_sensitive) THEN\n    PERFORM set_config('backbone.principal',old_person,true); PERFORM set_config('backbone.run',old_run,true); PERFORM set_config('backbone.secret',old_secret,true);\n    RETURN;\n  END IF;\n  mine := q.person = me.person AND gov.identity_person_task_access(q.task_id,me.person,false);\n  private_reason := coalesce(q.elsewhere_source, q.sensitive_source);\n  PERFORM gov._mark(p_run,\n    CASE WHEN q.tainted_untrusted THEN CASE WHEN mine\n      THEN 'other work it quoted, which had read ' || gov._strip_carried(q.untrusted_source)\n      ELSE 'other work it quoted, for another person, which had read content from outside the workspace' END END,\n    CASE WHEN q.tainted_sensitive THEN CASE WHEN mine\n      THEN 'other work it quoted, which had read ' || gov._strip_carried(private_reason)\n      ELSE 'other work it quoted, for another person, which had read private material' END END,\n    CASE WHEN q.tainted_sensitive AND (NOT mine OR q.task_id IS DISTINCT FROM me.task_id) THEN CASE WHEN mine\n      THEN 'other work it quoted, which had read ' || gov._strip_carried(private_reason)\n      ELSE 'other work it quoted, for another person, which had read private material' END END);\n  PERFORM set_config('backbone.principal',old_person,true); PERFORM set_config('backbone.run',old_run,true); PERFORM set_config('backbone.secret',old_secret,true);\nEXCEPTION WHEN OTHERS THEN\n  PERFORM set_config('backbone.principal',old_person,true); PERFORM set_config('backbone.run',old_run,true); PERFORM set_config('backbone.secret',old_secret,true);\n  RAISE;\nEND\n$$;\n\n-- gov/quote_marks.sql\n\n-- A run, while it acts, says what other work its digest quotes: effects, questions, runs, tasks,\n-- imported memory proposals. It takes what each carries (I-7): a quoted run's marks,\n-- a private task's words, an imported memory nobody accepted. Entries that name nothing are ignored.\nCREATE OR REPLACE FUNCTION gov.quote_marks(p_run uuid, p_quotes jsonb) RETURNS void\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE\n  old_person text:=coalesce(current_setting('backbone.principal',true),''); old_run text:=coalesce(current_setting('backbone.run',true),''); old_secret text:=coalesce(current_setting('backbone.secret',true),'');\n  ws uuid := sec.current_workspace();\n  me record;\n  q uuid;\n  p record;\nBEGIN\n  IF sec.current_run() IS DISTINCT FROM p_run THEN\n    RAISE EXCEPTION 'not_in_run: only the run that acts says what it quotes';\n  END IF;\n  IF jsonb_typeof(p_quotes) IS DISTINCT FROM 'object' THEN\n    RAISE EXCEPTION 'invalid: quotes are named by kind';\n  END IF;\n  PERFORM set_config('backbone.run','',true); PERFORM set_config('backbone.secret','',true); PERFORM set_config('backbone.principal',sec.system_principal()::text,true);\n  SELECT r.task_id, gov._run_person(r.id) AS person INTO me FROM app.runs r WHERE r.workspace_id = ws AND r.id = p_run;\n  FOR q IN\n    SELECT e.run_id FROM app.effects e WHERE e.workspace_id = ws AND e.id::text IN (SELECT gov._quoted_ids(p_quotes, 'effects'))\n    UNION ALL\n    SELECT e.run_id FROM app.decisions d JOIN app.effects e ON e.workspace_id = d.workspace_id AND e.id = d.subject_id\n    WHERE d.workspace_id = ws AND d.id::text IN (SELECT gov._quoted_ids(p_quotes, 'decisions'))\n    UNION ALL\n    SELECT r.id FROM app.runs r WHERE r.workspace_id = ws AND r.id::text IN (SELECT gov._quoted_ids(p_quotes, 'runs'))\n  LOOP\n    IF q IS NOT NULL THEN\n      PERFORM gov._quote_run(p_run, q);\n    END IF;\n  END LOOP;\n  IF EXISTS (SELECT FROM app.tasks t WHERE t.workspace_id = ws AND t.id::text IN (SELECT gov._quoted_ids(p_quotes, 'tasks'))\n             AND t.visibility = 'private' AND t.id <> me.task_id) THEN\n    PERFORM gov._mark(p_run, NULL, 'private tasks whose words it quoted', 'private tasks whose words it quoted');\n  END IF;\n  FOR p IN SELECT * FROM app.memory_proposals mp WHERE mp.workspace_id = ws AND mp.id::text IN (SELECT gov._quoted_ids(p_quotes, 'proposals')) LOOP\n    PERFORM gov._mark(p_run,\n      CASE WHEN p.status <> 'accepted' THEN 'a memory imported from ' || gov._source_name(p.source) || ' that '\n                                            || gov._person_name(p.person_id) || ' never accepted' END,\n      gov._person_name(p.person_id) || '’s memory');\n  END LOOP;\n  PERFORM set_config('backbone.principal',old_person,true); PERFORM set_config('backbone.run',old_run,true); PERFORM set_config('backbone.secret',old_secret,true);\nEXCEPTION WHEN OTHERS THEN\n  PERFORM set_config('backbone.principal',old_person,true); PERFORM set_config('backbone.run',old_run,true); PERFORM set_config('backbone.secret',old_secret,true);\n  RAISE;\nEND\n$$;\n\n-- gov/unregister_piece.sql\n\n-- Unregister a piece. Refused while any effect it carried is UNKNOWN or still being sent: nobody can\n-- yet say what it did. Otherwise its runs stop, its effects not yet sent are cancelled, and work\n-- bound to it is refused from then on. Only the workspace's owner or an admin unregisters, never a\n-- run. Returns false when it was already unregistered.\nCREATE OR REPLACE FUNCTION gov.unregister_piece(p_piece uuid) RETURNS boolean\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE\n  old_person text:=coalesce(current_setting('backbone.principal',true),''); old_run text:=coalesce(current_setting('backbone.run',true),''); old_secret text:=coalesce(current_setting('backbone.secret',true),'');\n  ws uuid := sec.current_workspace();\n  me uuid := sec.current_principal();\n  p record;\n  r record;\n  e record;\nBEGIN\n  IF me IS NULL THEN\n    RAISE EXCEPTION 'no_identity: the session acts as nobody';\n  END IF;\n  IF sec.names_run() THEN\n    RAISE EXCEPTION 'not_by_runs: a piece is unregistered by the person or an admin';\n  END IF;\n  IF sec.principal_kind(me) IS DISTINCT FROM 'person' OR NOT sec.is_admin(me) THEN\n    RAISE EXCEPTION 'role: only the workspace''s owner or an admin unregisters a piece';\n  END IF;\n  PERFORM gov._lock_workspace();\n  SELECT * INTO p FROM app.pieces x WHERE x.workspace_id = ws AND x.id = p_piece;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'not_found: no such piece in this workspace';\n  END IF;\n  IF p.unregistered_at IS NOT NULL THEN\n    RETURN false;\n  END IF;\n  PERFORM set_config('backbone.run','',true); PERFORM set_config('backbone.secret','',true); PERFORM set_config('backbone.principal',sec.system_principal()::text,true);\n  IF EXISTS (SELECT FROM app.effects x JOIN app.runs y ON y.workspace_id = x.workspace_id AND y.id = x.run_id\n             WHERE x.workspace_id = ws AND y.piece_id = p_piece AND x.status IN ('unknown', 'dispatching')) THEN\n    RAISE EXCEPTION 'unsettled: an effect this piece carried is UNKNOWN or still being sent; settle it first';\n  END IF;\n  UPDATE app.pieces SET unregistered_at = clock_timestamp(), unregistered_by = me WHERE workspace_id = ws AND id = p_piece;\n  FOR r IN SELECT id FROM app.runs x WHERE x.workspace_id = ws AND x.piece_id = p_piece AND x.status IN ('queued', 'running', 'waiting') LOOP\n    PERFORM gov._stop_run(r.id, 'cancelled', 'piece unregistered');\n  END LOOP;\n  FOR e IN SELECT x.id FROM app.effects x JOIN app.runs y ON y.workspace_id = x.workspace_id AND y.id = x.run_id\n           WHERE x.workspace_id = ws AND y.piece_id = p_piece AND x.status IN ('proposed', 'awaiting_checker', 'allowed', 'claimed') LOOP\n    PERFORM gov._cancel_effect(e.id, 'piece unregistered');\n  END LOOP;\n  PERFORM gov._append('piece.unregistered', p_piece::text, jsonb_build_object('piece', p.piece, 'digest', p.digest),me);\n  PERFORM set_config('backbone.principal',old_person,true); PERFORM set_config('backbone.run',old_run,true); PERFORM set_config('backbone.secret',old_secret,true);\n  RETURN true;\nEXCEPTION WHEN OTHERS THEN\n  PERFORM set_config('backbone.principal',old_person,true); PERFORM set_config('backbone.run',old_run,true); PERFORM set_config('backbone.secret',old_secret,true);\n  RAISE;\nEND\n$$;\n\n-- gov/give_connector_signature.sql\n\n-- Only a person can form this authority. Caller-selected ids and historical replay do not exist.\nCREATE OR REPLACE FUNCTION gov.give_connector_signature(p_connection uuid, p_tool text, p_definition text) RETURNS uuid\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog\nAS $$\nDECLARE\n  me uuid;\n  ws uuid := sec.current_workspace();\n  connection record;\n  signature uuid;\nBEGIN\n  IF sec.names_run() THEN RAISE EXCEPTION 'not_by_runs: a run never gives a signature'; END IF;\n  PERFORM gov._lock_workspace();\n  me := gov._person();\n  IF p_definition IS NULL OR p_definition !~ '^[a-f0-9]{64}$' THEN\n    RAISE EXCEPTION 'invalid: a signature binds an opaque SHA-256 definition digest';\n  END IF;\n  SELECT c.* INTO connection FROM app.connections c WHERE c.workspace_id=ws AND c.id=p_connection;\n  IF NOT FOUND THEN RAISE EXCEPTION 'not_found: no such connection in this workspace'; END IF;\n  IF connection.scope='person' AND connection.owner_id IS DISTINCT FROM me THEN\n    RAISE EXCEPTION 'someone_else: only its person signs their connection';\n  END IF;\n  IF NOT EXISTS (SELECT FROM app.connection_tools t WHERE t.workspace_id=ws AND t.connection_id=p_connection\n      AND t.name=p_tool AND t.removed_at IS NULL) THEN\n    RAISE EXCEPTION 'not_found: no such current tool on this connection';\n  END IF;\n  -- Supersede abandoned grants too: a lost give reply never leaves an extra live authority.\n  PERFORM gov.end_connector_signature(s.id,'superseded') FROM app.connector_signatures s\n    WHERE s.workspace_id=ws AND s.person_id=me AND s.connection_id=p_connection\n      AND s.tool_name=p_tool AND s.ended_at IS NULL;\n  INSERT INTO app.connector_signatures(workspace_id,person_id,connection_id,tool_name,operation,definition_digest)\n    VALUES(ws,me,p_connection,p_tool,'mcp.'||connection.slug||'.'||p_tool,p_definition) RETURNING id INTO signature;\n  PERFORM gov._append('signature.given',signature::text,jsonb_build_object(\n    'signature',signature,'connection',p_connection,'tool_hash',sec.digest(p_tool),'definition_digest',sec.digest(p_definition)),me);\n  RETURN signature;\nEND\n$$;\n\n-- gov/_may_answer.sql\n\n-- Whether principal `p_me` may answer the question as a person (decision.answer), with this\n-- verdict; refused with the reason otherwise. Who answers:\n--   a question for a named person:   that person alone;\n--   a question for any person:       an owner or admin, from outside the proposer's delegation\n--                                    tree when the question is strict (in a team or company);\n--   a verifier's question:           the verifier (verifier.answer, with its proof); in its place\n--                                    the person named on it, or for an unnamed one an independent\n--                                    owner or admin. A strict question's named person may decline\n--                                    it but not approve it.\n-- The proposer never answers its own question.\nCREATE OR REPLACE FUNCTION gov._may_answer(p_decision uuid, p_me uuid, p_verdict text) RETURNS void\nLANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE\n  d record;\n  independent boolean;\nBEGIN\n  IF p_me IS NULL OR sec.current_principal() IS DISTINCT FROM p_me THEN RAISE EXCEPTION 'no_identity: the checker is no longer active'; END IF;\n  SELECT * INTO d FROM app.decisions x WHERE x.workspace_id = sec.current_workspace() AND x.id = p_decision;\n  IF NOT FOUND OR d.status <> 'open' THEN\n    RAISE EXCEPTION 'not_open: the question is not open';\n  END IF;\n  IF p_me = d.proposer_id THEN\n    RAISE EXCEPTION 'own_proposal: the proposer never answers its own question';\n  END IF;\n  independent := sec.workspace_is_personal(d.workspace_id) OR NOT d.is_strict\n                 OR sec.checker_independent(d.workspace_id, d.proposer_id, p_me, true);\n  IF d.checker_kind = 'verifier' THEN\n    IF sec.is_verifier(p_me) THEN\n      RAISE EXCEPTION 'verifier_proof: a verifier answers with its persisted response (verifier.answer)';\n    END IF;\n    IF sec.principal_kind(p_me) <> 'person' THEN\n      RAISE EXCEPTION 'verifier_only: the question belongs to a verifier';\n    END IF;\n    IF d.checker_id IS NOT NULL THEN\n      IF p_me <> d.checker_id THEN\n        RAISE EXCEPTION 'verifier_only: the question belongs to the verifier and the person whose material it is';\n      END IF;\n      IF p_verdict = 'approved' AND NOT independent THEN\n        RAISE EXCEPTION 'not_independent: the person may decline it, but approving it is the verifier''s';\n      END IF;\n      RETURN;\n    END IF;\n    IF NOT sec.is_admin(p_me) THEN\n      RAISE EXCEPTION 'verifier_only: the question belongs to a verifier, or in its place an owner or admin';\n    END IF;\n    IF NOT independent THEN\n      RAISE EXCEPTION 'not_independent: the checker sits in the proposer''s delegation tree';\n    END IF;\n    RETURN;\n  END IF;\n  IF d.checker_id IS NOT NULL THEN\n    IF p_me <> d.checker_id THEN\n      RAISE EXCEPTION 'someone_else: the question belongs to another person';\n    END IF;\n    RETURN;\n  END IF;\n  IF NOT sec.is_admin(p_me) THEN\n    RAISE EXCEPTION 'role: an owner or an admin answers this question';\n  END IF;\n  IF NOT independent THEN\n    RAISE EXCEPTION 'not_independent: the checker sits in the proposer''s delegation tree';\n  END IF;\nEND\n$$;\n\n-- gov/identity_effect_decider_access.sql\n\n-- The exact question is a capability, including an independent checker for\n-- an unnamed elevation. A role alone still grants no other project's payloads.\nCREATE OR REPLACE FUNCTION gov.identity_effect_decider_access(p_decision uuid) RETURNS boolean\nLANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog\nAS $$\n  SELECT NOT sec.names_run() AND sec.current_principal() IS NOT NULL AND EXISTS(\n    SELECT FROM app.decisions d WHERE d.workspace_id=sec.current_workspace() AND d.id=p_decision\n      AND (d.checker_id=sec.viewer() OR d.answered_by=sec.current_principal()\n        OR (d.checker_kind='verifier' AND sec.is_verifier(sec.current_principal()))\n        OR (d.subject_kind='effect' AND gov.may_decide(d.id))))\n$$;\n\n-- gov/identity_material_scope.sql\n\n-- NULL is an explicit workspace material scope, not an unbound task. Only\n-- live people and verifiers can read it; guests/verifiers cannot write it.\n-- Task checks stay closed, including orphan tasks and unnamed sessions.\nGRANT USAGE ON SCHEMA gov TO backbone_owner;\nCREATE FUNCTION gov.identity_material_scope(p_task uuid,p_write boolean) RETURNS boolean\nLANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog\nAS $$\nDECLARE principal uuid:=sec.current_principal(); role text;\nBEGIN\n  IF p_task IS NOT NULL THEN RETURN gov.identity_task_access(p_task,p_write); END IF;\n  IF principal=sec.system_principal() THEN RETURN true; END IF;\n  IF principal IS NULL THEN RETURN false; END IF;\n  IF NOT p_write AND sec.is_verifier(principal) THEN RETURN true; END IF;\n  role:=sec.role_of(sec.viewer());\n  RETURN coalesce(role IN('owner','admin','member') OR (NOT p_write AND role='guest'),false);\nEND\n$$;\nREVOKE ALL ON FUNCTION gov.identity_material_scope(uuid,boolean) FROM PUBLIC,backbone_operator;\nGRANT EXECUTE ON FUNCTION gov.identity_material_scope(uuid,boolean) TO backbone_app,backbone_owner;\n\nSET ROLE backbone_owner;\n\n-- app/identity_document_policies.sql\n\n-- Preserve the native API's explicit workspace documents without reopening the\n-- general task guard for missing bindings or unnamed sessions.\nDROP POLICY identity_project_read ON app.documents;\nCREATE POLICY identity_project_read ON app.documents AS RESTRICTIVE FOR SELECT TO backbone_app USING(gov.identity_material_scope(task_id,false));\nDROP POLICY identity_project_crossing_read ON app.documents;\nCREATE POLICY identity_project_crossing_read ON app.documents AS RESTRICTIVE FOR SELECT TO backbone_gov USING(gov.identity_material_scope(task_id,false));\nDROP POLICY identity_project_insert ON app.documents;\nCREATE POLICY identity_project_insert ON app.documents AS RESTRICTIVE FOR INSERT TO backbone_gov WITH CHECK(gov.identity_material_scope(task_id,true));\nDROP POLICY identity_project_update ON app.documents;\nCREATE POLICY identity_project_update ON app.documents AS RESTRICTIVE FOR UPDATE TO backbone_gov USING(true) WITH CHECK(gov.identity_material_scope(task_id,true));\n-- A source explicitly recorded for neither a task nor a run is workspace\n-- evidence. The native recorder checks its origin; project sources keep their binding.\nDROP POLICY identity_project_read ON app.episodes;\nCREATE POLICY identity_project_read ON app.episodes AS RESTRICTIVE FOR SELECT TO backbone_app USING(CASE WHEN task_id IS NULL AND run_id IS NOT NULL THEN gov.identity_run_access(run_id,false) ELSE gov.identity_material_scope(task_id,false) END);\nDROP POLICY identity_project_crossing_read ON app.episodes;\nCREATE POLICY identity_project_crossing_read ON app.episodes AS RESTRICTIVE FOR SELECT TO backbone_gov USING(CASE WHEN task_id IS NULL AND run_id IS NOT NULL THEN gov.identity_run_access(run_id,false) ELSE gov.identity_material_scope(task_id,false) END);\nDROP POLICY identity_project_insert ON app.episodes;\nCREATE POLICY identity_project_insert ON app.episodes AS RESTRICTIVE FOR INSERT TO backbone_gov WITH CHECK(CASE WHEN task_id IS NULL AND run_id IS NOT NULL THEN gov.identity_run_access(run_id,true) ELSE gov.identity_material_scope(task_id,true) END);\nDROP POLICY identity_project_update ON app.episodes;\nCREATE POLICY identity_project_update ON app.episodes AS RESTRICTIVE FOR UPDATE TO backbone_gov USING(true) WITH CHECK(CASE WHEN task_id IS NULL AND run_id IS NOT NULL THEN gov.identity_run_access(run_id,true) ELSE gov.identity_material_scope(task_id,true) END);\n\nSET ROLE backbone_gov;\n\n-- gov/identity_document_access.sql\n\n-- A version inherits the document's actual project or explicit workspace scope.\nREVOKE USAGE ON SCHEMA gov FROM backbone_owner;\nCREATE OR REPLACE FUNCTION gov.identity_document_access(p_document uuid,p_write boolean) RETURNS boolean\nLANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE task uuid;\nBEGIN\n  SELECT task_id INTO task FROM app.documents WHERE workspace_id=sec.current_workspace() AND id=p_document;\n  IF NOT FOUND THEN RETURN false; END IF;\n  RETURN gov.identity_material_scope(task,p_write);\nEND\n$$;\n\nRESET ROLE;\n"} as const);
